// Logic template
var calc_output = [];

var a = parseFloat(a);
var b = parseFloat(b);
var c = parseFloat(c);
var d = parseFloat(d);
var e = parseFloat(e);
var f = parseFloat(f);

// returns the highest numeric value among valid inputs
function getHighestValue() {
  // Filter out NaN or null/undefined values
  var arr = [a, b, c, d, e, f].filter(v => !isNaN(v));

  // If no valid numeric inputs, return null
  if (arr.length === 0) return null;

  return Math.max(...arr);
}

// Compute highest value
var highest = getHighestValue();

// Assign grade label
var grade;
if (highest === null || highest === 0) {
  grade = "Grade not defined";
} else {
  grade = "Grade " + highest;
}

// Output
calc_output.push({
  name: 'mini',
  value: grade,
  value_text: '',
  message: 'ICANS Consensus Grading'
});

